# walk dirs
def walk(path):
    if path.startswith(os.path.sep) and not os.path.isdir(path): return []
    res=[]
    for p in gg.walk(path):
        t=open(p[0]).read().replace('\\n','\n')
        if 'Demo pair' in t: res.append(p[0])
    return res
