    P=sorted(set(P))
    n=len(P); lo=0
    for i in range(n):
        while i-1>=lo:
            pass
    h=P[:]
    k=max(range(n),key=lambda p:(P[p[0]]-P[0][0])**2+(p[1]-P[0][1])**2)
    rem=[p for p in P if p!=P[k]]
    H=[]
    for anchor in (min(P,key=lambda p:p[0]),max(P,key=lambda p:p[0])):
        pass
