    L=[]
    for p in sorted(P,key=lambda p:(p[0],p[1])):
        while len(L)>=2 and ccw(L[-2],L[-1],p)<=0: L.pop()
        L.append(p)
    U=[]
    for p in reversed(sorted(P,key=lambda p:(p[0],p[1]))):
        while len(U)>=2 and ccw(U[-2],U[-1],p)<=0: U.pop()
        U.append(p)
    h=L[:-1]+U[:-1]
    return h
